const tabId = 480038377;
const queries = [
  "site:oru.edu \"director of student activities\"",
  "site:oru.edu \"student activities director\"",
  "site:oru.edu \"student activities\" director",
  "site:oru.edu \"student activities\" coordinator",
  "site:oru.edu/about-oru/administration",
  "Oral Roberts University student activities staff directory"
];

for (const q of queries) {
  const url = `https://duckduckgo.com/?q=${encodeURIComponent(q)}`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });
  const results = await browserjs(tabId, () => {
    return Array.from(document.querySelectorAll('a[data-testid="result-title-a"], a[href*="oru.edu"]')).map(a => ({
      title: a.innerText.trim(),
      href: a.href,
      snippet: a.closest('article, .result, div')?.innerText?.slice(0, 200)
    })).filter(x => x.href.includes('oru.edu'));
  });
  console.log(`Query: ${q} -> Found:`, results.length);
  if (results.length > 0) {
    console.log(JSON.stringify(results.slice(0, 5), null, 2));
    break;
  }
}

