const tabId = 480038377;
const queries = [
  'site:edfenergy.com "salary review"',
  'site:edfenergy.com "salary reviews"',
  'site:careers.edfenergy.com "salary review"',
  'site:careers.edfenergy.com "salary reviews"',
  'site:edfenergy.com graduate "salary"',
  '"EDF Energy" graduate "salary review"'
];

for (const q of queries) {
  const url = `https://duckduckgo.com/?q=${encodeURIComponent(q)}`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load" });
  const results = await browserjs(tabId, () => {
    return Array.from(document.querySelectorAll('article, [data-layout="organic"]')).map(el => {
      const title = el.querySelector('h2')?.innerText;
      const link = el.querySelector('a[data-testid="result-title-a"]')?.href;
      const snippet = el.innerText;
      return { title, link, snippet: snippet?.slice(0, 300) };
    }).filter(x => x.title && x.link);
  });
  console.log(`Query: ${q} -> count: ${results.length}`);
  if (results.length > 0) {
    console.log(JSON.stringify(results.slice(0, 3), null, 2));
  }
}

