const pdfjsLib = await import("https://esm.run/pdfjs-dist@3.11.174");

const pdfUrl = "https://www.edfenergy.com/sites/default/files/graduate_and_placement_brochure_2023_2024.pdf";
const res = await tool.fetch_url({ url: pdfUrl });

// In fetch_url, body is string (latin1/utf8) or base64. Let's see if we can get arrayBuffer
// Actually, let's fetch it via browserjs or fetch
const tabId = 480038377;
const pdfText = await browserjs(tabId, async (url) => {
  const resp = await fetch(url);
  const blob = await resp.blob();
  const arrayBuffer = await blob.arrayBuffer();

  // import pdfjs inside page
  const pdfjs = await import("https://esm.run/pdfjs-dist@3.11.174");
  pdfjs.GlobalWorkerOptions.workerSrc = "https://esm.run/pdfjs-dist@3.11.174/build/pdf.worker.min.js";

  const loadingTask = pdfjs.getDocument({ data: arrayBuffer });
  const pdf = await loadingTask.promise;
  let fullText = "";
  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const content = await page.getTextContent();
    const strings = content.items.map(item => item.str);
    fullText += `--- PAGE ${i} ---\n` + strings.join(" ") + "\n";
  }
