// Convert res.body string to Uint8Array
const len = res.body.length;
const bytes = new Uint8Array(len);
for (let i = 0; i < len; i++) {
  bytes[i] = res.body.charCodeAt(i) & 0xff;
}

const doc = await pdfjs.getDocument({ data: bytes.buffer }).promise;
console.log("PDF pages:", doc.numPages);

let fullPdfText = "";
for (let i = 1; i <= doc.numPages; i++) {
  const page = await doc.getPage(i);
  const textContent = await page.getTextContent();
  const pageStr = textContent.items.map(item => item.str).join(" ");
  fullPdfText += `=== PAGE ${i} ===\n${pageStr}\n\n`;
}

